using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);

        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);

        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDifferentItems_SumsAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 2);

        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothEntriesCounted()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 1);

        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_ExcludedFromTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 1);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ReturnsFalse()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsFalse(_cart.RemoveItem("SKU-999"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAllEntries()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 7.00m, 2);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    [DataRow("A", 1.50, 2, 3.00)]
    [DataRow("B", 0.99, 10, 9.90)]
    [DataRow("C", 100.00, 1, 100.00)]
    public void GetTotal_VariousInputs_ReturnsExpected(
        string sku, double price, int qty, double expected)
    {
        _cart.AddItem(sku, (decimal)price, qty);

        Assert.AreEqual((decimal)expected, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAddAndRemove_ReflectsCurrentItems()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 20.00m, 1);
        _cart.RemoveItem("A");
        _cart.AddItem("C", 5.00m, 3);

        Assert.AreEqual(35.00m, _cart.GetTotal());
    }
}

